def cells(rr, cc, h):
    return [(rr + i, cc + j) for i in range(h) for j in range(5 - h)]

def layout(r, big):
    H, W = (18, 48) if big else (12, 32)
    occ = set(); B = []                       # bricks: (row, col, h) with h=2 (2x3, pins up/down) or 3 (3x2, pins left/right)
    def ok(rr, cc, h):
        return all(0 <= a < H and 0 <= b < W and (a, b) not in occ for a, b in cells(rr, cc, h))
    target = 72 if big else 32
    for _ in range(4000):
        if len(B) >= target: break
        if B and r.random() < 0.8:            # attach to an existing brick, same orientation, random pin width
            rr, cc, h = r.choice(B)
            d = 3 - r.choice((1, 2, 3)); s = r.choice((-2, 2)); t = r.choice((-d, d))
            nr, nc = (rr + s, cc + t) if h == 2 else (rr + t, cc + s)
        else:                                  # scatter
            h = r.choice((2, 3)); nr, nc = r.randrange(H), r.randrange(W)
        if ok(nr, nc, h):
            occ.update(cells(nr, nc, h)); B.append((nr, nc, h))
    E = []
    for i, a in enumerate(B):
        for j, b in enumerate(B):
            if j <= i: continue
            w = width(a, b)
            if w: E.append((i, j, w))
    return B, E

def width(a, b):
    if a[2] != b[2]: return 0
    p, q = abs(a[0] - b[0]), abs(a[1] - b[1])
    if a[2] == 3: p, q = q, p
    return 3 - q if p == 2 and q < 3 else 0

def uniform(E, B):
    h = [sum(1 for e in E if e[2] == w) for w in (1, 2, 3)]
    v = sum(1 for b in B if b[2] == 3)
    return min(h) >= 0.27 * len(E) and max(h) <= 0.40 * len(E) and 0.3 * len(B) <= v <= 0.7 * len(B)

def render(B, lab, r):
    fill = r.choice("._-~:*")
    rows = [a for b in B for a, _ in cells(*b)]; cols = [c for b in B for _, c in cells(*b)]
    r0, c0 = min(rows), min(cols)
    g = [[fill] * (max(cols) - c0 + 1) for _ in range(max(rows) - r0 + 1)]
    for i, b in enumerate(B):
        for a, c in cells(*b): g[a - r0][c - c0] = lab[i]
    return "\n".join("".join(row) for row in g)

def parse(s):
    """Exactly the scorer's greedy brick parse; None if the text does not tile."""
    g = [list(w) for w in s.split("\n")]; B = []
    for rr, w in enumerate(g):
        for k, L in enumerate(w):
            if L.isupper():
                for h in (2, 3):
                    try:
                        if all(g[rr + i][k + j] == L for i, j in cells(0, 0, h)): break
                    except IndexError:
                        pass
                else:
                    return None
                for i, j in cells(0, 0, h): g[rr + i][k + j] = ""
                B.append((rr, k, h, L))
    return B

def solve(clue):
    x, y = clue[0], int(clue[1:])
    r = random.Random(clue)
    others = [ch for ch in string.ascii_uppercase if ch != x]
    for attempt in range(300):
        B, E = layout(r, y >= 5)
        if len(E) < max(5 * y, 12) or not uniform(E, B): continue
        E1 = [e for e in E if e[2] == 1]
        for _ in range(20):
            r.shuffle(E1); V = set(); cnt = 0
            for i, j, w in E1:
                if cnt == y: break
                V2 = V | {i, j}
                c2 = sum(1 for a, b, ww in E1 if a in V2 and b in V2)
                if c2 <= y: V, cnt = V2, c2
            if cnt != y: continue
            X = set(V)
            for i in r.sample(range(len(B)), len(B)):          # decoy x bricks: only 2/3-pin or cross-orientation contacts
                if i not in X and r.random() < 0.3 and not any((a == i and b in X) or (b == i and a in X) for a, b, w in E1):
                    X.add(i)
            pal = r.sample(others, 6)
            lab = [x if i in X else r.choice(pal) for i in range(len(B))]
            if len(set(lab)) < 5: continue
            s = render(B, lab, r)
            P = parse(s)                                       # verify exactly as the scorer will
            if P and sum(a[3] == b[3] == x and width((a[0], a[1], a[2]), (b[0], b[1], b[2])) == 1 for a in P for b in P) // 2 == y:
                return s
    return ""

